CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', company_name text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING (id=auth.uid());
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING (id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'owner' CHECK(role IN ('owner','staff')));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.company_worlds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL UNIQUE, name text NOT NULL DEFAULT 'Mi Isla', state jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.company_worlds TO authenticated; GRANT ALL ON public.company_worlds TO service_role;
ALTER TABLE public.company_worlds ENABLE ROW LEVEL SECURITY;
CREATE POLICY world_read ON public.company_worlds FOR SELECT TO authenticated USING(owner_id=auth.uid());
CREATE POLICY world_insert ON public.company_worlds FOR INSERT TO authenticated WITH CHECK(owner_id=auth.uid() AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='owner'));
CREATE POLICY world_update ON public.company_worlds FOR UPDATE TO authenticated USING(owner_id=auth.uid()) WITH CHECK(owner_id=auth.uid());
CREATE FUNCTION public.suite_signup_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,display_name,company_name) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'display_name',''),COALESCE(NEW.raw_user_meta_data->>'company_name','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'owner'); RETURN NEW; END $$;
CREATE TRIGGER suite_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.suite_signup_profile();
CREATE FUNCTION public.suite_validate_world() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE b jsonb; plots text[] := '{}'; p text; BEGIN IF jsonb_typeof(NEW.state)<>'object' THEN RAISE EXCEPTION 'Invalid world'; END IF; FOR b IN SELECT value FROM jsonb_array_elements(COALESCE(NEW.state->'buildings','[]'::jsonb)) LOOP p:=b->>'plot'; IF p IS NULL OR p=ANY(plots) THEN RAISE EXCEPTION 'Plot already occupied'; END IF; plots:=array_append(plots,p); END LOOP; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER suite_world_updated BEFORE INSERT OR UPDATE ON public.company_worlds FOR EACH ROW EXECUTE FUNCTION public.suite_validate_world();
ALTER PUBLICATION supabase_realtime ADD TABLE public.company_worlds;